use async_trait::async_trait;

pub type PendingAuthCacheResult<T> = Result<T, Box<dyn std::error::Error + Send + Sync>>;

/// Short-lived key/value cache for the TOTP 2FA flow. Backed by the SAME
/// Redis client already used for `StatusPageCache` (see
/// `infra::RedisPendingAuthCache` — same `redis::Client`, just a
/// different key namespace; no new connection pool is created for this
/// feature).
///
/// Two distinct namespaces share this one port:
///
/// - "pending secret": the not-yet-confirmed TOTP secret generated by
///   `EnableTotpUseCase`, keyed by user id, TTL >= 10 minutes. Only
///   promoted to `User.totp_secret` once `ConfirmTotpSetupUseCase`
///   verifies the user actually possesses it.
/// - "pending 2FA token": the opaque token `LoginUserUseCase` hands back
///   instead of a session JWT when `user.totp_enabled()` is true, keyed
///   by the random token itself (mapping to the pending user id), TTL >=
///   5 minutes. Redeemed exactly once by `VerifyTotpAndLoginUseCase`.
///
/// Unlike `StatusPageCache`, a cache miss here is a genuine failure (an
/// expired/invalid pending token or secret must reject the request) —
/// callers must NOT treat `get` returning `None` as "fall back to the
/// database", there is no database fallback for these ephemeral values.
#[async_trait]
pub trait PendingAuthCache: Send + Sync {
    /// Returns the value stored under `key`, if present and not expired.
    async fn get(&self, key: &str) -> PendingAuthCacheResult<Option<String>>;

    /// Atomically fetches and removes the value stored under `key`.
    /// Returns `None` if the key was not present (already consumed or
    /// expired). This is the single-use primitive used by
    /// `VerifyTotpAndLoginUseCase` to guarantee that a pending 2FA token
    /// cannot be replayed by two concurrent requests.
    async fn getdel(&self, key: &str) -> PendingAuthCacheResult<Option<String>>;

    /// Stores `value` under `key` with the given time-to-live.
    async fn set(&self, key: &str, value: &str, ttl_seconds: u64) -> PendingAuthCacheResult<()>;

    /// Removes `key`. Used to make pending secrets/tokens single-use —
    /// callers must delete on successful redemption so the same secret or
    /// token cannot be replayed.
    async fn delete(&self, key: &str) -> PendingAuthCacheResult<()>;
}

use std::sync::Arc;

#[async_trait]
impl<T> PendingAuthCache for Arc<T>
where
    T: PendingAuthCache + ?Sized,
{
    async fn get(&self, key: &str) -> PendingAuthCacheResult<Option<String>> {
        (**self).get(key).await
    }

    async fn getdel(&self, key: &str) -> PendingAuthCacheResult<Option<String>> {
        (**self).getdel(key).await
    }

    async fn set(&self, key: &str, value: &str, ttl_seconds: u64) -> PendingAuthCacheResult<()> {
        (**self).set(key, value, ttl_seconds).await
    }

    async fn delete(&self, key: &str) -> PendingAuthCacheResult<()> {
        (**self).delete(key).await
    }
}
